export const particleColours={"H": "#f8f6f2", "O": "#ed8b78", "C": "#71808c", "Ca": "#d4dfe7", "Mg": "#9aafbf", "S": "#f0b4a6", "Cl": "#b7c8d6", "P": "#ed8b78", "N": "#71808c", "E": "#f8f6f2", "Fe": "#b7c8d6", "Cu": "#f0b4a6", "Iplus": "#ed8b78", "Iminus": "#b7c8d6", "K": "#b7c8d6", "Focus": "#ed8b78", "X": "#b7c8d6", "Cube": "#ed8b78"};
export function bounds(atoms,padding=.75){if(!atoms.length)return {centre:[0,0,0],radius:1};const centre=[1,2,3].map(k=>(Math.min(...atoms.map(a=>a[k]))+Math.max(...atoms.map(a=>a[k])))/2);return {centre,radius:Math.max(1,...atoms.map(a=>Math.hypot(...centre.map((c,k)=>a[k+1]-c))+padding))};}
export function fitDistance(radius,aspect,fov=36){const half=fov*Math.PI/360,lim=Math.min(half,Math.atan(Math.tan(half)*aspect));return radius/Math.sin(lim)*1.08;}
export function zoomLimits(base){return {min:base*.55,max:base*2.5};}
export function projectAtoms(atoms){const points=atoms.map(a=>[a[1]+a[3]*.38,-a[2]+a[3]*.28]);if(!points.length)return [];const xs=points.map(a=>a[0]),ys=points.map(a=>a[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,scale=Math.min(310/Math.max(1,Math.max(...xs)-Math.min(...xs)),175/Math.max(1,Math.max(...ys)-Math.min(...ys)),85);return points.map(([x,y])=>[220+(x-cx)*scale,125+(y-cy)*scale]);}
export function stackedReadings(values){const seen=new Map();return values.map(value=>{const level=seen.get(value)||0;seen.set(value,level+1);return {value,level};});}
export const nobleBoiling=[{symbol:'He',value:-269},{symbol:'Ne',value:-246},{symbol:'Ar',value:-186}];
export function phaseKinds(state){if(state==='solid + liquid')return ['solid','liquid'];if(state==='liquid + gas')return ['liquid','gas'];if(['solid','liquid','gas'].includes(state))return [state];throw Error('Unknown phase');}
